def grid(x, y, xstep, ystep, xl, yl):
    return blank(x=x, y=y, xstep=xstep, ystep=ystep, xlabel=xl, ylabel=yl,
                 desc='Blank grid with labeled axes: horizontal %s from %s to %s (step %s), vertical %s from %s to %s (step %s).'
                      % (xl, x[0], x[1], xstep, yl, y[0], y[1], ystep))


