              sa('Check x = 6 in √(x + 3) + 3 = x.', 'Answer:', key='√9 + 3 = 6; a solution', note='Form required: the check and conclusion.'),
              tf('x = 5 satisfies √(2x - 1) = 3.', key=True, note='√9 = 3.'),
